import os, re

d = os.environ['RLM_SESSION_DIR']
session_name = os.path.basename(d)
sessions_path = os.path.normpath(os.path.join(d, '../../sessions', session_name + '.jsonl'))

t = open(sessions_path).read().replace('\\n', '\n')

matches = re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t)

G = {}
for mid in matches:
    k, h, w = mid[1], int(mid[2]), int(mid[3])
    end = mid.end()
    rows = [r.split() for r in t[end:].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

print("Loaded grids:", sorted(G.keys()))
for k, v in G.items():
    print(f"\n=== {k}: {len(v)}x{len(v[0])} ===")
    for row in v:
        print(row)

